using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Net;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Http;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

namespace PdfService.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class PdfGeneratorController : ControllerBase
    {
        private readonly IPdfRenderer _renderer;
        private readonly ITemplateStore _templateStore;

        public PdfGeneratorController(IPdfRenderer renderer, ITemplateStore templateStore)
        {
            _renderer = renderer;
            _templateStore = templateStore;
        }

        [HttpPost("render")]
        public async Task<IActionResult> RenderPdf([FromBody] JObject request)
        {
            var templateId = request["templateId"]?.ToString();
            if (string.IsNullOrEmpty(templateId))
                return BadRequest("templateId is required");

            var template = await _templateStore.GetTemplateAsync(templateId);
            if (template == null)
                return NotFound("Template not found");

            var context = BuildRenderContext(request["data"], template);
            var pdfBytes = await _renderer.RenderAsync(context);
            return File(pdfBytes, "application/pdf", $"{templateId}.pdf");
        }

        private RenderContext BuildRenderContext(JToken dataToken, PdfTemplate template)
        {
            var context = new RenderContext
            {
                Template = template,
                Variables = new Dictionary<string, object>()
            };

            if (dataToken == null) return context;

            foreach (var field in template.Fields)
            {
                var value = dataToken[field.Name];
                if (value == null) continue;

                context.Variables[field.Name] = ResolveFieldValue(value, field);
            }

            return context;
        }

        private object ResolveFieldValue(JToken value, TemplateField field)
        {
            switch (field.FieldType)
            {
                case FieldType.Text:
                    return SanitizeText(value.ToString());
                case FieldType.Number:
                    return value.ToObject<double>();
                case FieldType.Image:
                    return ResolveImageReference(value, field);
                case FieldType.RichContent:
                    return ResolveRichContent(value, field);
                default:
                    return value.ToString();
            }
        }

        private string SanitizeText(string input)
        {
            if (string.IsNullOrEmpty(input)) return input;
            return input.Replace("<", "&lt;").Replace(">", "&gt;")
                       .Replace("\"", "&quot;").Replace("'", "&#39;");
        }

        private ImageRef ResolveImageReference(JToken value, TemplateField field)
        {
            var url = value["url"]?.ToString();
            if (string.IsNullOrEmpty(url))
                return new ImageRef { Data = Array.Empty<byte>() };

            if (!IsAllowedImageSource(url))
                return new ImageRef { Data = Array.Empty<byte>() };

            return new ImageRef
            {
                Url = url,
                Width = value["width"]?.ToObject<int>() ?? field.DefaultWidth,
                Height = value["height"]?.ToObject<int>() ?? field.DefaultHeight
            };
        }

        private object ResolveRichContent(JToken value, TemplateField field)
        {
            if (value.Type == JTokenType.String)
            {
                return new RichContentBlock
                {
                    Html = SanitizeRichContent(value.ToString()),
                    AllowExternalResources = false
                };
            }

            if (value.Type == JTokenType.Object)
            {
                var contentType = value["type"]?.ToString() ?? "html";
                var content = value["content"];

                if (contentType == "reference")
                {
                    return ResolveContentReference(value, field);
                }

                return new RichContentBlock
                {
                    Html = SanitizeRichContent(content?.ToString() ?? ""),
                    AllowExternalResources = false
                };
            }

            return new RichContentBlock { Html = "", AllowExternalResources = false };
        }

        private object ResolveContentReference(JToken value, TemplateField field)
        {
            var refPath = value["path"]?.ToString();
            if (string.IsNullOrEmpty(refPath))
                return new RichContentBlock { Html = "", AllowExternalResources = false };

            // Validate the reference path against allowed patterns
            if (!IsValidReferencePath(refPath))
                return new RichContentBlock { Html = "", AllowExternalResources = false };

            // The proxy header X-Forwarded-Prefix determines the internal resolution base
            var forwardedPrefix = HttpContext.Request.Headers["X-Forwarded-Prefix"].FirstOrDefault() ?? "";
            var resolvedBase = GetInternalServiceBase(forwardedPrefix);

            // ContentReference is resolved by the renderer with SSRF protections
            // However, the type returned here determines how the renderer processes it
            var options = value["options"];

            // Safe deserialization without TypeNameHandling - no type confusion possible
            ContentReferenceOptions refOptions;
            if (options != null && options.Type == JTokenType.Object)
            {
                refOptions = options.ToObject<ContentReferenceOptions>(JsonSerializer.Create(
                    new JsonSerializerSettings
                    {
                        TypeNameHandling = TypeNameHandling.None
                    }));
            }
            else
            {
                refOptions = new ContentReferenceOptions();
            }

            return new ContentReference
            {
                BasePath = resolvedBase,
                ReferencePath = refPath,
                Options = refOptions
            };
        }

        private bool IsValidReferencePath(string path)
        {
            if (path.Contains("..") || path.Contains("://"))
                return false;
            return path.StartsWith("/content/") || path.StartsWith("content/");
        }

        private string GetInternalServiceBase(string forwardedPrefix)
        {
            var baseUrl = "http://content-service.internal:8080";
            if (string.IsNullOrEmpty(forwardedPrefix))
                return baseUrl;

            forwardedPrefix = forwardedPrefix.TrimEnd('/');

            // Validate the attacker-influenced forwarded prefix to prevent
            // SSRF / URL manipulation (protocol-relative, traversal, host injection).
            if (!IsValidForwardedPrefix(forwardedPrefix))
                return baseUrl;

            return baseUrl + forwardedPrefix;
        }

        private bool IsValidForwardedPrefix(string prefix)
        {
            if (string.IsNullOrEmpty(prefix))
                return false;

            // Must be a single-level absolute path segment prefix, not a protocol-relative
            // URL or a path traversal attempt.
            if (!prefix.StartsWith("/") || prefix.StartsWith("//"))
                return false;
            if (prefix.Contains("..") || prefix.Contains("://") ||
                prefix.Contains("\\") || prefix.Contains("@"))
                return false;

            // Only allow a conservative set of URL-path-safe characters.
            foreach (var c in prefix)
            {
                bool ok = char.IsLetterOrDigit(c) || c == '/' || c == '-' || c == '_';
                if (!ok) return false;
            }

            return true;
        }

        private bool IsAllowedImageSource(string url)
        {
            if (Uri.TryCreate(url, UriKind.Absolute, out var uri))
            {
                var allowedHosts = new[] { "cdn.example.com", "images.example.com" };
                return Array.Exists(allowedHosts, h => h.Equals(uri.Host, StringComparison.OrdinalIgnoreCase));
            }
            return url.StartsWith("/images/");
        }

        private string SanitizeRichContent(string html)
        {
            // Strip script tags and event handlers
            html = System.Text.RegularExpressions.Regex.Replace(html, @"<script[^>]*>[\s\S]*?</script>", "", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            html = System.Text.RegularExpressions.Regex.Replace(html, @"on\w+\s*=\s*\"[^\"]*\"", "", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            return html;
        }
    }

    public interface IPdfRenderer
    {
        Task<byte[]> RenderAsync(RenderContext context);
    }

    public interface ITemplateStore
    {
        Task<PdfTemplate> GetTemplateAsync(string templateId);
    }

    public class RenderContext
    {
        public PdfTemplate Template { get; set; }
        public Dictionary<string, object> Variables { get; set; }
    }

    public class PdfTemplate
    {
        public string Id { get; set; }
        public string Name { get; set; }
        public List<TemplateField> Fields { get; set; } = new List<TemplateField>();
    }

    public class TemplateField
    {
        public string Name { get; set; }
        public FieldType FieldType { get; set; }
        public int DefaultWidth { get; set; } = 200;
        public int DefaultHeight { get; set; } = 200;
    }

    public enum FieldType { Text, Number, Image, RichContent }

    public class ImageRef
    {
        public string Url { get; set; }
        public byte[] Data { get; set; }
        public int Width { get; set; }
        public int Height { get; set; }
    }

    public class RichContentBlock
    {
        public string Html { get; set; }
        public bool AllowExternalResources { get; set; }
    }

    public class ContentReference
    {
        public string BasePath { get; set; }
        public string ReferencePath { get; set; }
        public ContentReferenceOptions Options { get; set; }
    }

    public class ContentReferenceOptions
    {
        public bool Cache { get; set; } = true;
        public int TimeoutMs { get; set; } = 5000;
        public string Format { get; set; } = "html";
    }
}
